<script>const report=@json($report);function copyReport(){navigator.clipboard.writeText(JSON.stringify(report,null,2))}function save(data,name,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click()}function downloadJson(){save(JSON.stringify(report,null,2),'phone-intelligence.json','application/json')}function downloadCsv(){const rows=[['Number','Country','Country Code','Type','Status','Confidence','Source','Source Type'],...report.phones.map(p=>[p.number,p.country,p.country_code,p.type,p.status,p.confidence,p.source,p.source_type])];save(rows.map(r=>r.map(v=>'"'+String(v||'').replaceAll('"','""')+'"').join(',')).join('\n'),'phone-intelligence.csv','text/csv')}</script>
